import itertools, random
from problems import ThreeSat, NaeThreeSat
from reduce import reduce

def lit_true(l, a): return a[abs(l)] if l>0 else not a[abs(l)]
def solve_3(inst):
    m=inst["num_vars"]; cl=inst["clauses"]
    for bits in itertools.product([0,1],repeat=m):
        a={i+1:bool(bits[i]) for i in range(m)}
        if all(any(lit_true(l,a) for l in c) for c in cl): return True
    return False
def solve_nae(inst):
    m=inst["num_vars"]; cl=inst["clauses"]
    for bits in itertools.product([0,1],repeat=m):
        a={i+1:bool(bits[i]) for i in range(m)}
        if all(not all(lit_true(l,a) for l in c) and any(lit_true(l,a) for l in c) for c in cl):
            return True
    return False

rng=random.Random(999)
run=passed=0
for _ in range(3000):
    m=rng.randint(3,9); n=rng.randint(0,14)
    cl=[]
    for _ in range(n):
        vs=rng.sample(range(1,m+1),3)
        cl.append([v if rng.random()<0.5 else -v for v in vs])
    inst={"num_vars":m,"clauses":cl}
    ThreeSat.validate(inst)
    out=reduce(inst); NaeThreeSat.validate(out)
    run+=1
    if solve_3(inst)==solve_nae(out): passed+=1
    else: print("FAIL",inst,out); break
print("stress run",run,"passed",passed)
EOF
